 GrowthUnit("issabel","Issabel، Asterisk، SIP و RTP","VoIP","پیشرفته","Registration، Endpoint، Dialplan و مسیر Media را بررسی کن.","asterisk -rvvv\ncore show channels\npjsip show endpoints\npjsip show registrations\npjsip show contacts\ndialplan show\njournalctl -u asterisk --since '30 minutes ago'\ntcpdump -ni any 'port 5060 or port 5061'","در نسخه‌های جدید PJSIP رایج است؛ SIP Signaling و RTP Media دو مسیر متفاوت‌اند.","تماس برقرار می‌شود اما صدا یک‌طرفه است؛ RTP، NAT، Firewall و Codec را بررسی کن.","تماس SIP برقرار است اما صدا یک‌طرفه؛ کدام لایه محتمل‌تر است؟",listOf("مسیر RTP/Media","DNS MX","NTFS ACL","RAID Cache"),0,"SIP سیگنالینگ را انجام می‌دهد؛ RTP حامل صدای واقعی است."),
 GrowthUnit("fxo","FXO و خطوط شهری","VoIP","پیشرفته","خط فیزیکی، Port State، Trunk، Dial Pattern و Disconnect را بررسی کن.","Gateway UI: FXO port state, trunk status, call logs\nAsterisk: pjsip show endpoints; pjsip show contacts; dialplan show; core show channels","Tone، Impedance، Gain و Disconnect Supervision وابسته به اپراتور و مدل Gateway است.","خط پس از قطع تماس اشغال می‌ماند؛ Busy/Disconnect Supervision و تنظیمات منطقه‌ای را بررسی کن.","آیا Tone و Impedance برای همه کشورها یکسان است؟",listOf("بله","خیر؛ وابسته به اپراتور و مدل است","فقط به DNS وابسته است","فقط به VLAN بستگی دارد"),1,"پارامترهای سیگنالینگ آنالوگ به کشور، اپراتور و سخت‌افزار وابسته‌اند."),
 GrowthUnit("zeroclient","Zero Client و Thin Client","کلاینت","متوسط","Broker، DNS، NTP، TLS، VLAN و Firmware را بررسی کن.","ipconfig /all\nResolve-DnsName broker.example.local\nTest-NetConnection broker.example.local -Port 443\nVendor Console: device inventory, firmware, session status","پورت‌ها به سازنده و پروتکل وابسته‌اند؛ 4172 یا 3389 را بدون مستندات محصول قطعی فرض نکن.","کلاینت به Broker وصل نمی‌شود؛ DHCP، DNS، NTP، Certificate و ظرفیت Session Host را بررسی کن.","آیا پورت 4172 برای همه Zero Clientها الزامی است؟",listOf("بله، همه محصولات","خیر؛ وابسته به Vendor و پروتکل است","فقط برای DHCP","فقط برای SQL"),1,"پورت‌های ارتباطی به سازنده، نسخه و پروتکل وابسته‌اند."),
 GrowthUnit("accounting","حسابداری پارسیان و سپیدار","نرم‌افزار سازمانی","متوسط","کلاینت، سرور برنامه، SQL، مجوز و Backup را مرحله‌ای بررسی کن.","Resolve-DnsName <accounting-server>\nTest-NetConnection <server> -Port <actual-sql-port>\nGet-Service | Where-Object {\$_.DisplayName -match 'SQL|Sepidar|Parsian'}\nGet-WinEvent -LogName Application -MaxEvents 100","پورت واقعی SQL، نسخه کلاینت/سرور، Driver، مجوز و فضای دیسک را ثبت کن؛ ساختار داخلی نسخه‌ها متفاوت است.","فقط یک کلاینت حسابداری خطا دارد؛ DNS، نسخه، Driver و Credential را مقایسه کن.","برای اصلاح داده مالی کدام روش امن‌تر است؟",listOf("UPDATE مستقیم جدول بدون Backup","ابزار رسمی برنامه و تأیید مسئول مالی","حذف MDF","تغییر Collation فوری"),1,"دستکاری مستقیم جداول مالی می‌تواند یکپارچگی داده و پشتیبانی سازنده را مخدوش کند."),
 GrowthUnit("monitoring","مانیتورینگ، لاگ و ظرفیت","زیرساخت","پیشرفته","CPU، RAM، Disk latency و زمان رخداد را با Baseline مقایسه کن.","Linux: uptime; free -h; iostat -xz 1 5; vmstat 1 5\nWindows: Get-Counter '\\Processor(_Total)\\% Processor Time'\nLinux logs: journalctl --since '1 hour ago'\nWindows: Get-WinEvent -LogName System -MaxEvents 200","روند زمانی و NTP هماهنگ لازم است؛ یک Snapshot به‌تنهایی علت را ثابت نمی‌کند.","قطع تماس همزمان با خطای WAN رخ داده؛ Log سوئیچ، Firewall، PBX و ISP را هم‌زمان تطبیق بده.","چرا NTP برای عیب‌یابی چند سامانه مهم است؟",listOf("یکسان‌سازی زمان رخدادها","تخصیص IP","رمزگذاری RAID","تغییر VLAN"),0,"ساعت هماهنگ ترتیب رخدادها را در سامانه‌های مختلف قابل اتکا می‌کند.")

 GrowthUnit("mikrotik-firewall","MikroTik Firewall، NAT و Hardening","امنیت شبکه","پیشرفته","قواعد Firewall را با ترتیب، Interface List، Connection State و اصل حداقل دسترسی تحلیل کن.","/ip firewall filter print stats detail\n/ip firewall nat print stats\n/ip firewall raw print stats\n/ip firewall connection print count-only\n/ip service print\n/ip ssh print\n/tool torch interface=ether1\n# مدیریت امن: ابتدا Safe Mode و دسترسی مدیریتی جایگزین را آماده کن.","Input/Forward/Output را تفکیک کن؛ Established/Related، Drop نهایی، محدودسازی Winbox/SSH به شبکه مدیریت و ثبت شمارنده Ruleها را کنترل کن. NAT جایگزین Firewall نیست.","پس از افزودن Rule، مدیریت روتر قطع شده؛ ترتیب Rule، مسیر مدیریت، Safe Mode و دسترسی کنسول را بررسی کن؛ تغییر را بدون مسیر بازگشت اعمال نکن.","آیا وجود masquerade به‌تنهایی روتر را در برابر اتصال ورودی امن می‌کند؟",listOf("بله","خیر؛ فیلتر ورودی و مدیریت امن جداگانه لازم است","فقط برای IPv6","فقط در حالت Bridge"),1,"NAT کنترل دسترسی نیست. Input chain، سرویس‌های مدیریتی و سیاست Drop باید مستقل و محدود باشند."),
 GrowthUnit("issabel-security","امنیت Issabel و Asterisk، SIP و Firewall","امنیت VoIP","پیشرفته","سطح دسترسی PBX، داخلی‌ها، SIP Trunk، Firewall و لاگ تماس را ایمن کن.","asterisk -rx 'pjsip show endpoints'\nasterisk -rx 'pjsip show contacts'\nasterisk -rx 'pjsip show transports'\nasterisk -rx 'core show settings'\nss -lntup\nfirewall-cmd --list-all\njournalctl -u asterisk --since '1 hour ago'\n# بررسی لاگ‌ها و تماس‌ها؛ دستورها را با نسخه Issabel تطبیق بده.","SIP را فقط از IPهای مورد اعتماد بپذیر؛ رمز داخلی قوی و یکتا، محدودیت تماس بین‌الملل، Fail2ban، به‌روزرسانی، Backup و دسترسی مدیریتی VPN لازم است. RTP range باید مستند و محدود باشد.","ثبت‌نام SIP از اینترنت ناشناس و تماس‌های غیرعادی دیده می‌شود؛ CDR، Asterisk log، IP مبدأ، نرخ تماس، Trunk و سیاست خروجی را بررسی و حساب مشکوک را طبق رویه Incident مهار کن.","برای مدیریت امن PBX کدام گزینه بهتر است؟",listOf("بازکردن SIP و پنل مدیریت به کل اینترنت","VPN یا Allowlist، رمز یکتا، محدودیت تماس و پایش لاگ","استفاده از رمز یکسان همه داخلی‌ها","خاموش‌کردن لاگ‌ها"),1,"PBX هدف رایج سوءاستفاده Toll Fraud است؛ دسترسی محدود، رمزهای قوی، محدودیت مقصد/هزینه و پایش CDR ضروری‌اند. منبع آموزشی تکمیلی: https://pbxshop.co/free-issabel/"),
 GrowthUnit("wireless-rf","آنتن وایرلس، لینک نقطه‌به‌نقطه و RF","شبکه بی‌سیم","متوسط","Line of Sight، Fresnel Zone، فرکانس، کانال، پهنای کانال و تراز لینک را بررسی کن.","Linux: iw dev; iw dev wlan0 link; iw dev wlan0 station dump\nLinux scan (مجاز): iw dev wlan0 scan | less\nMikroTik: /interface wifi print detail\n/interface wifi registration-table print stats\n/interface monitor-traffic <interface>\n# ابزارهای Vendor: spectrum analyzer, alignment, link test","RSSI، SNR، CCQ/airtime، نویز، Retry، کانال و ظرفیت دو سمت را با هم بررسی کن؛ Fresnel Zone و موانع در مسیر مهم‌اند.","لینک در ظهر افت می‌کند؛ نویز هم‌کانال، تداخل، تغییرات دید مستقیم، دما، کابل/PoE و خطای کانکتور را مقایسه کن.","برای ارزیابی کیفیت لینک کدام ترکیب مفیدتر است؟",listOf("فقط RSSI","RSSI به‌همراه SNR، نویز، Retry و ظرفیت واقعی","فقط نام SSID","فقط IP Gateway"),1,"قدرت سیگنال به‌تنهایی کیفیت را نشان نمی‌دهد؛ SNR و تداخل و نرخ Retry تعیین‌کننده‌اند."),
 GrowthUnit("python-ops","Python برای اتوماسیون و عیب‌یابی IT","برنامه‌نویسی","مقدماتی تا متوسط","اسکریپت امن برای بررسی چند Host، پورت و پردازش فایل CSV بنویس.","python --version\npy -m venv .venv\n# Windows: .venv\\Scripts\\Activate.ps1\n# Linux/macOS: source .venv/bin/activate\npython -m pip install --upgrade pip\npython -c \"import socket; s=socket.create_connection(('example.com',443),timeout=3); print('TCP OK'); s.close()\"\npython -m http.server 8000 --bind 127.0.0.1","از Timeout، مدیریت Exception، logging، virtual environment و فایل requirements.txt استفاده کن؛ رمزها را در کد قرار نده.","گزارش روزانه وضعیت سرورها لازم است؛ فهرست مجاز Hostها را از CSV بخوان، اتصال TCP را با Timeout تست و نتیجه را همراه زمان ثبت کن.","چرا استفاده از venv مناسب است؟",listOf("برای جداسازی وابستگی‌های هر پروژه","برای افزایش مجوز Administrator","برای بازکردن همه پورت‌ها","برای حذف لاگ‌ها"),0,"محیط مجازی وابستگی‌های Python پروژه را از سیستم و پروژه‌های دیگر جدا می‌کند."),
 GrowthUnit("git-ops","Git و GitHub برای مدیریت تغییرات زیرساخت","ابزار توسعه","مقدماتی تا متوسط","تغییرات را قابل بازبینی، نسخه‌بندی و بازگشت‌پذیر مدیریت کن.","git --version\ngit clone <repo-url>\ngit status --short\ngit switch -c feature/change-name\ngit diff --check\ngit diff\ngit add <file>\ngit commit -m 'docs: describe change'\ngit log --oneline --decorate -10\ngit fetch origin\ngit diff origin/main...HEAD","قبل از Commit وضعیت و Diff را بخوان؛ Secret، فایل پشتیبان، کلید خصوصی و خروجی دارای اطلاعات محرمانه را وارد Repository نکن.","تغییر تنظیمات شبکه نیاز به بازبینی دارد؛ Branch جدا، Commit کوچک، Diff و Pull Request تهیه کن و Rollback plan را ثبت کن.","کدام دستور تغییرات ثبت‌نشده را نشان می‌دهد؟",listOf("git status","git push --force","git clean -xfd","git reset --hard"),0,"git status وضعیت فایل‌های تغییرکرده، staged و untracked را نشان می‌دهد."),
 GrowthUnit("windows-services-process","Windows Services، Process و مدیریت فایل باز","Windows","متوسط","سرویس‌ها، پردازش‌ها، پورت‌های Listen و فایل‌های باز SMB را پیدا و کنترل کن.","Get-Service | Sort-Object Status,Name\nGet-CimInstance Win32_Service | Select Name,State,StartMode,ProcessId\nGet-Process | Sort-Object CPU -Descending | Select -First 15\nGet-NetTCPConnection -State Listen\nGet-Process -Id <PID>\nStop-Process -Id <PID>   # فقط پس از شناسایی و تأیید\nRestart-Service -Name <ServiceName>\nGet-SmbOpenFile\nClose-SmbOpenFile -FileId <FileId> -Force\n# CMD: tasklist /svc ; taskkill /PID <PID> /T","قبل از Stop/Close مالک سرویس، PID، کاربران متصل و اثر سرویس را بررسی کن؛ Stop-Process و Close-SmbOpenFile می‌توانند کاربر را از کار بیندازند.","فایل اشتراکی قفل شده؛ Get-SmbOpenFile را بررسی، کاربر/مسیر/FileId را تأیید و فقط در پنجره نگهداری فایل مشخص را ببند.","برای بستن فایل باز روی SMB کدام Cmdlet است؟",listOf("Close-SmbOpenFile","Get-SmbShare","Get-NetRoute","gpupdate"),0,"Close-SmbOpenFile فایل مشخص را از سمت سرور می‌بندد؛ ابتدا شناسه و مالک را بررسی کن."),
 GrowthUnit("windows-share-security","Windows File Sharing، NTFS و SMB Security","Windows","متوسط تا پیشرفته","Share، NTFS ACL، SMB version، نشست‌ها و دسترسی مؤثر را ممیزی کن.","Get-SmbShare\nGet-SmbShareAccess -Name <ShareName>\nGet-SmbSession\nGet-SmbOpenFile\nGet-SmbServerConfiguration | Select EnableSMB1Protocol,EnableSMB2Protocol\nGet-Acl 'D:\\Shares\\Finance' | Format-List\nicacls D:\\Shares\\Finance\nTest-NetConnection <fileserver> -Port 445","SMB1 را در صورت عدم نیاز غیرفعال کن؛ دسترسی را با گروه‌های AD و حداقل مجوز طراحی کن؛ Share و NTFS ACL هر دو مؤثرند.","یک کاربر به پوشه مالی دسترسی غیرمجاز دارد؛ گروه‌های تو در تو، ACL وراثتی، Share ACL و عضویت کاربر را بررسی کن.","برای دسترسی مؤثر فایل اشتراکی چه چیزی باید بررسی شود؟",listOf("فقط Share ACL","فقط NTFS ACL","هر دو ACL و گروه‌های مؤثر کاربر","فقط DNS"),2,"دسترسی نهایی از Share permission، NTFS permission و عضویت گروه‌ها تأثیر می‌گیرد."),
 GrowthUnit("log-analysis","تحلیل لاگ، Event ID و همبستگی رخدادها","مانیتورینگ و امنیت","پیشرفته","لاگ‌های Windows، Linux، Firewall، Switch و PBX را بر اساس زمان و منبع همبسته کن.","Windows: Get-WinEvent -FilterHashtable @{LogName='System'; StartTime=(Get-Date).AddHours(-2)}\nWindows: Get-WinEvent -LogName Security -MaxEvents 100\nLinux: journalctl --since '2 hours ago' -p warning\nLinux: journalctl -u ssh --since today\nLinux: grep -iE 'error|failed|denied' /var/log/* 2>/dev/null\nNetwork: show logging (Cisco); /log print (MikroTik)\nAsterisk: journalctl -u asterisk --since '1 hour ago'","NTP، Timezone، Hostname، User، Source IP، Event ID و Correlation ID را ثبت کن؛ لاگ خام را حفظ و زنجیره نگهداری را رعایت کن.","کاربر می‌گوید ارتباط قطع شده؛ زمان دقیق را با لاگ پورت سوئیچ، DHCP، Firewall، DNS، Windows و PBX تطبیق بده.","اولین گام برای همبستگی لاگ چند سامانه چیست؟",listOf("هماهنگ‌سازی زمان با NTP و Timezone","پاک‌کردن لاگ‌ها","Restart همه سرورها","غیرفعال‌کردن Audit"),0,"بدون ساعت هماهنگ، ترتیب رخدادها و علت‌یابی بین سامانه‌ها قابل اتکا نیست."),
 GrowthUnit("ethical-pentest","امنیت، آسیب‌شناسی و تست نفوذ مجاز","امنیت اطلاعات","پیشرفته","چرخه ارزیابی امنیت را با مجوز کتبی، Scope و محیط آزمایشگاهی اجرا و مستندسازی کن.","# Asset inventory and written authorization first\nnmap -sV --top-ports 100 <LAB-IP>\nnmap -sT -p 22,80,443,445 <LAB-IP>\n# TLS review: testssl.sh <LAB-HOST>\n# Web proxy: OWASP ZAP in passive/baseline mode\n# Linux hardening: ss -lntup; sudo lynis audit system\n# Windows baseline: Get-NetFirewallProfile; Get-MpComputerStatus","Scope، زمان، IPهای مجاز، نرخ درخواست، مجوز مالک، Backup و روش توقف را پیش از تست ثبت کن؛ روی سامانه ثالث یا IP عمومی بدون مجوز اسکن نکن.","در تست داخلی، یک پورت غیرمنتظره باز است؛ مالک سرویس، نسخه، نیاز کسب‌وکار، Rule Firewall و ریسک را ثبت و برای اصلاح گزارش بده.","پیش‌نیاز اصلی تست نفوذ چیست؟",listOf("داشتن ابزار اسکن","مجوز کتبی و Scope مشخص","اسکن گسترده اینترنت","غیرفعال‌کردن مانیتورینگ"),1,"ارزیابی امنیتی باید مجاز، محدود به Scope و دارای برنامه توقف و گزارش اصلاحی باشد."),
 GrowthUnit("port-reference","مرجع پورت‌های متداول و رنج‌های TCP/UDP","مرجع سریع","مقدماتی تا پیشرفته","پورت، پروتکل، جهت ارتباط و وابستگی نسخه/محصول را در طراحی Firewall تشخیص بده.","Port range: 0-1023 Well-known; 1024-49151 Registered; 49152-65535 Dynamic/Private (IANA). Ephemeral client range may differ by OS.\n20/21 TCP FTP; 22 TCP SSH; 23 TCP Telnet (avoid); 25 TCP SMTP; 53 TCP/UDP DNS; 67/68 UDP DHCP; 69 UDP TFTP; 80 TCP HTTP; 110 TCP POP3; 123 UDP NTP; 143 TCP IMAP; 161/162 UDP SNMP; 389 TCP/UDP LDAP; 443 TCP HTTPS; 445 TCP SMB; 465/587 TCP mail submission; 514 UDP syslog; 636 TCP LDAPS; 993/995 TCP IMAPS/POP3S.\n1433 TCP SQL Server default; 3306 TCP MySQL; 3389 TCP RDP; 5432 TCP PostgreSQL; 5060 UDP/TCP SIP; 5061 TCP TLS-SIP; 10000-20000 UDP common RTP example only (verify PBX config); 1812/1813 UDP RADIUS; 2049 TCP/UDP NFS; 2375/2376 Docker API; 5985/5986 TCP WinRM; 8080/8443 TCP alternate web.\nCheck: Get-NetTCPConnection; Get-NetUDPEndpoint; ss -lntup; nmap -sV -p <ports> <authorized-host>","شماره پورت به‌تنهایی کافی نیست؛ TCP/UDP، سمت مبدأ/مقصد، Listener واقعی، نسخه محصول و نیاز ارتباطی را مشخص کن. IANA rangeها را با ephemeral range سیستم‌عامل اشتباه نگیر.","قانون Firewall برای SQL نوشته شده اما اتصال برقرار نیست؛ پروتکل TCP، پورت Instance واقعی، مسیر، Source IP و Listener را بررسی کن.","کدام محدوده طبق IANA Dynamic/Private است؟",listOf("0-1023","1024-49151","49152-65535","1433-65535"),2,"IANA محدوده 49152 تا 65535 را Dynamic/Private ثبت می‌کند؛ محدوده موقت کلاینت ممکن است در سیستم‌عامل متفاوت پیکربندی شود."),
 GrowthUnit("command-toolbox","جعبه‌ابزار دستورات شبکه و مدیریت سیستم","مرجع سریع","مقدماتی تا پیشرفته","دستور مناسب را برای بررسی DNS، Route، Port، فایل، پردازش و سرویس انتخاب کن.","Windows: ipconfig /all; ipconfig /flushdns; route print; arp -a; nslookup; Resolve-DnsName <host>; Test-NetConnection <host> -Port 443; tracert <host>; pathping <host>\nPowerShell: Get-Service; Restart-Service <name>; Get-Process; Stop-Process -Id <PID>; Get-NetTCPConnection; Get-NetAdapter; Get-WinEvent -LogName System -MaxEvents 50; Get-SmbOpenFile; Close-SmbOpenFile -FileId <id>\nLinux: ip -br a; ip route; ping -c 4 <host>; traceroute <host>; dig <name>; ss -lntup; lsof -i :443; systemctl status <svc>; journalctl -u <svc>; ps aux; kill -TERM <PID>; fuser -v <file>\nCisco: show ip interface brief; show interfaces counters errors; show vlan brief; show interfaces trunk; show mac address-table; show ip route; show logging\nMikroTik: /interface print; /ip address print; /ip route print; /ip firewall filter print stats; /log print\nFortiGate: get system status; get router info routing-table all; diagnose sys session stat; diagnose sniffer packet any 'host <IP>' 4 20 l","اول از فرمان‌های Read-only استفاده کن؛ پیش از Stop، Kill، Close، تغییر Firewall یا حذف فایل، هدف و اثر را تأیید و Backup/Change window داشته باش.","یک سرویس پاسخ نمی‌دهد؛ ابتدا DNS، Route، TCP port، Listener و Log را بررسی کن و فقط پس از شناسایی PID/Service اقدام اصلاحی انجام بده.","برای خاتمه امن یک پردازش در Linux کدام سیگنال مناسب‌تر است؟",listOf("kill -9 در اولین مرحله","kill -TERM و بررسی نتیجه","حذف فایل اجرایی","خاموش‌کردن سیستم"),1,"SIGTERM فرصت خاتمه کنترل‌شده می‌دهد؛ SIGKILL آخرین راه است و باید فقط با تشخیص PID صحیح استفاده شود."),
 GrowthUnit("firewall-design","طراحی سیاست Firewall و Segment بندی","امنیت شبکه","پیشرفته","قواعد ورودی/خروجی را بر پایه Zone، Source، Destination، Service و Logging طراحی کن.","Inventory: source subnet, destination, protocol, port, business owner\nCisco: show access-lists; show ip access-lists\nMikroTik: /ip firewall filter print stats; /ip firewall address-list print\nFortiGate: show firewall policy; diagnose firewall iprope lookup <src-ip> <src-port> <dst-ip> <dst-port> <protocol>\nWindows: Get-NetFirewallProfile; Get-NetFirewallRule -Enabled True\nLinux: sudo nft list ruleset","Default deny برای ورودی، محدودیت مدیریت به Management VLAN/VPN، Ruleهای مستند و دارای مالک، Logging کنترل‌شده و بازبینی دوره‌ای رعایت شود.","دوربین‌ها به سرور مالی دسترسی دارند؛ ماتریس جریان بساز و فقط سرویس ضروری بین VLANها را مجاز کن.","اصل مناسب طراحی Rule چیست؟",listOf("Any-to-any برای راحتی","حداقل دسترسی و Default Deny همراه مستندسازی","بازکردن تمام پورت‌ها","خاموش‌کردن لاگ"),1,"قواعد باید فقط جریان‌های موردنیاز کسب‌وکار را اجازه دهند و مالک و علت مشخص داشته باشند."),
 GrowthUnit("incident-response","پاسخ به رخداد امنیتی و حفظ شواهد","امنیت اطلاعات","پیشرفته","رخداد را مهار، شواهد را حفظ و بازیابی را با ترتیب کنترل‌شده انجام بده.","Record: UTC/local time, hostname, user, source IP, event IDs\nWindows: Get-NetTCPConnection; Get-Process; Get-WinEvent -LogName Security -MaxEvents 200\nLinux: date -Is; ss -plant; ps auxf; journalctl --since '30 minutes ago'\nNetwork: export firewall/session logs; preserve switch port counters\n# isolate via approved EDR/Firewall procedure; preserve evidence before cleanup","زمان، Hash فایل شواهد، مالک، زنجیره تحویل و اقدام انجام‌شده را ثبت کن؛ قبل از جمع‌آوری شواهد سیستم را بی‌دلیل خاموش یا پاک‌سازی نکن.","هشدار Login غیرعادی روی سرور مالی دریافت شده؛ حساب/میزبان را طبق Runbook مهار، لاگ و نشست‌ها را حفظ و دامنه اثر را مشخص کن.","در رخداد امنیتی چرا پاک‌سازی فوری سیستم اشتباه است؟",listOf("چون شواهد و ردپا از بین می‌رود","چون DNS کند می‌شود","چون VLAN تغییر می‌کند","چون پورت‌ها افزایش می‌یابد"),0,"حفظ شواهد برای تعیین دامنه، ریشه‌یابی و گزارش رخداد ضروری است.")

)

@Composable
fun GrowthPathScreen(preferences: SharedPreferences) {
    val uriHandler = LocalUriHandler.current
    val saved = remember { mutableStateOf(preferences.getStringSet("growth_completed_v1", emptySet())?.toSet() ?: emptySet()) }
    var selectedId by rememberSaveable { mutableStateOf("") }
    var answer by rememberSaveable { mutableIntStateOf(-1) }
    var submitted by rememberSaveable { mutableStateOf(false) }
    val unit = growthUnits.firstOrNull { it.id == selectedId }
    val correct = unit != null && answer == unit.answer
    fun markDone(id: String) {
        val updated = saved.value + id
        saved.value = updated
        preferences.edit().putStringSet("growth_completed_v1", updated).apply()
    }
    LazyColumn(Modifier.fillMaxSize().padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        item {
            Card(Modifier.fillMaxWidth()) {
                Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("مسیر رشد تخصصی IT", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)
                    Text("درس‌های عملیاتی، دستورهای واقعی، سناریوهای عیب‌یابی و آزمون تعاملی؛ قابل استفاده بدون اینترنت.")
                    Text(saved.value.size.toString() + " از " + growthUnits.size + " درس تکمیل شده")
                    LinearProgressIndicator(progress = { saved.value.size.toFloat() / growthUnits.size }, modifier = Modifier.fillMaxWidth())
                    Text(growthUnits.size.toString() + " درس تخصصی · " + growthUnits.map { it.group }.distinct().size + " حوزه")
                    OutlinedButton(onClick = { uriHandler.openUri("https://github.com/MrUtility01/MindUnlock/blob/feature/mindunlock-core-modules/docs/operations/field-command-handbook-fa.md") }, modifier = Modifier.fillMaxWidth()) {
                        Text("باز کردن دفترچه کامل دستورات و عیب‌یابی")
                    }
                }
            }
        }
        if (unit != null) {
            item { OutlinedButton(onClick = { selectedId = ""; answer = -1; submitted = false }) { Text("بازگشت به فهرست مسیرها") } }
            item {
                Card(Modifier.fillMaxWidth()) {
                    Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        Text(unit.group + " · " + unit.level, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelLarge)
                        Text(unit.title, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)
                        Text("هدف آموزشی", fontWeight = FontWeight.Bold)
                        Text(unit.objective)
                        Text("آزمایشگاه دستورها", fontWeight = FontWeight.Bold)
                        Text(unit.commands, style = MaterialTheme.typography.bodyMedium)
                        Text("خروجی و تفسیر", fontWeight = FontWeight.Bold)
                        Text(unit.expected)
                        Text("سناریوی میدانی", fontWeight = FontWeight.Bold)
                        Text(unit.scenario)
                        Text("آزمون درس", fontWeight = FontWeight.Bold)
                        Text(unit.question)
                        unit.options.forEachIndexed { index, option ->
                            Row(Modifier.fillMaxWidth().clickable(enabled = !submitted) { answer = index }, horizontalArrangement = Arrangement.Start) {
                                RadioButton(selected = answer == index, onClick = { if (!submitted) answer = index }, enabled = !submitted)
                                Text(option, modifier = Modifier.padding(top = 12.dp))
                            }
                        }
                        if (!submitted) {
                            Button(onClick = { if (answer >= 0) submitted = true }, enabled = answer >= 0, modifier = Modifier.fillMaxWidth()) { Text("ثبت پاسخ") }
                        } else {
                            Text(if (correct) "پاسخ صحیح است." else "پاسخ صحیح: " + unit.options[unit.answer],
                                color = if (correct) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error,
                                fontWeight = FontWeight.Bold)
                            Text(unit.explanation)
                            Button(onClick = { markDone(unit.id); selectedId = ""; answer = -1; submitted = false }, modifier = Modifier.fillMaxWidth()) { Text("ثبت تکمیل درس") }
                            OutlinedButton(onClick = { answer = -1; submitted = false }, modifier = Modifier.fillMaxWidth()) { Text("تکرار آزمون") }
                        }
                    }
                }
            }
        } else {
            items(growthUnits, key = { it.id }) { item ->
                Card(Modifier.fillMaxWidth().clickable { selectedId = item.id; answer = -1; submitted = false }) {
                    Column(Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                        Text(item.group + " · " + item.level, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelMedium)
                        Text(item.title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                        Text(if (saved.value.contains(item.id)) "تکمیل شده" else "شروع درس و آزمون")
                    }
                }
            }
        }
    }
}
